head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#f5f3e7" value="#f5f3e7"/><Variable name="page.text" description="Text color" type="color" default="#263e2d" value="#263e2d"/><Variable name="theme.accent" description="Accent color" type="color" default="#8d472e" value="#8d472e"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Lora', Georgia, serif;--body:Arial, sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
.site-header{padding:30px 5%;display:flex;justify-content:space-between;align-items:center}.brand{font:italic 25px 'Lora', Georgia,serif}nav{display:flex;gap:25px;font-size:12px}.garden-hero{margin:35px 5% 65px;display:grid;grid-template-columns:1.05fr 1fr;gap:50px;align-items:center}.kicker{font-size:10px;letter-spacing:1.8px;text-transform:uppercase}.garden-hero h1{font:normal clamp(48px,5.7vw,79px)/1.04 'Lora', Georgia,serif;letter-spacing:-3px}.lead{max-width:365px;line-height:1.8;font-size:15px}.garden-hero a,.garden-end a{display:inline-block;border-bottom:1px solid;padding-bottom:7px;margin-top:20px;font-size:12px}.handnote{font:italic 19px 'Lora', Georgia,serif;color:#8d472e;margin-top:38px}.garden-hero figure{margin:0;transform:rotate(2deg)}.garden-hero svg{width:100%;border-radius:48% 48% 3px 3px;display:block}.garden-hero figcaption{font:italic 12px 'Lora', Georgia,serif;text-align:center;margin-top:15px}.garden-season{padding:30px 5%;background:#dce3c8;display:flex;gap:32px;align-items:center}.season-sun{font-size:60px;color:#7f5731}.garden-season h2{font:normal 28px 'Lora', Georgia,serif;margin:5px 0}.garden-season p:not(.kicker){font-size:13px}.garden-season a{margin-left:auto;white-space:nowrap;font-size:12px}.garden-paths{padding:70px 5%}.section-top{text-align:center;margin-bottom:32px}.section-top h2{font:normal 38px 'Lora', Georgia,serif}.path-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.path-grid a{padding:35px 27px;min-height:225px;border:1px solid #bbc4a7;border-radius:100px 100px 3px 3px;text-align:center;transition:transform .25s,background .25s}.path-grid a:nth-child(2){background:#e8d9bc}.path-grid a:nth-child(3){background:#e2e7d6}.path-grid span{font-size:9px;letter-spacing:1px}.path-grid h3{font:normal 26px 'Lora', Georgia,serif;margin:25px 0 12px}.path-grid p{font-size:13px;line-height:1.65}.path-grid b{font-size:11px;font-weight:400}.path-grid a:hover,.path-grid a:focus-visible{transform:translateY(-5px);background:#d4ddbc}.latest{padding:10px 5% 65px}.section-heading{font:normal 36px 'Lora', Georgia,serif;border-bottom:1px solid #b5c0a3;padding-bottom:20px}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.post-media{aspect-ratio:5/4;background:#dce3c8;border-radius:5px 45px 5px 5px;object-fit:cover}.post-meta{font-size:9px;letter-spacing:1px;text-transform:uppercase;color:#526744}.post-title{font:normal 26px/1.2 'Lora', Georgia,serif}.post-excerpt{font-size:13px;line-height:1.7}.garden-end{text-align:center;background:#263e2d;color:#f5f3e7;padding:60px 5%}.garden-end h2{font:normal 38px/1.25 'Lora', Georgia,serif}.garden-end p:not(.kicker){font-size:13px;max-width:440px;margin:auto;line-height:1.8}.site-footer{padding:35px 5%;display:flex;justify-content:space-between;align-items:center;gap:20px;font-size:11px}.site-footer strong{font:italic 22px 'Lora', Georgia,serif}@media(max-width:700px){.site-header{flex-direction:column;gap:20px}.garden-hero{grid-template-columns:1fr;gap:30px}.garden-hero h1{font-size:52px}.garden-hero figure{max-width:450px;margin:auto}.garden-season{flex-wrap:wrap;gap:14px}.garden-season a{margin-left:0}.path-grid,.posts-grid{grid-template-columns:1fr}.path-grid a{border-radius:45px 45px 3px 3px;min-height:0}.site-footer{flex-direction:column;text-align:center}}
:focus-visible{outline:2px solid currentColor;outline-offset:5px}img,svg{max-width:100%}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
h1,h2,h3{font-family:'Lora', Georgia, serif}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
